res_goal = primitives.call(name="get_cliport_task_language_goal")
print("Goal:", res_goal.output if res_goal.ok else res_goal)

res_obs = primitives.call(
    name="observe_cliport_rgbd",
    include_raw=False,
    query="pack all the green and red blocks into the brown box",
)
print("Obs ok:", res_obs.ok)

res_inst = primitives.call(
    name="inspect_cliport_instances",
    query="green and red blocks and brown box",
)
if res_inst.ok:
    for inst in res_inst.output.get("instances", []):
        print(
            {
                "id": inst.get("object_id"),
                "color": inst.get("color_name") or inst.get("rgb_mean"),
                "rgb": inst.get("rgb_mean"),
                "size": inst.get("size") or inst.get("bbox_size"),
                "pose0": inst.get("pose0"),
                "bbox": inst.get("bbox"),
            }
        )
else:
    print("Inst error:", res_inst)

